SELECT L.DOMAIN_ID , L.COMPANY_CD , L.LABEL_ID , L.LABEL_NM , L.UPDATE_USR , L.UPDATE_DT , L.CREATE_USR , L.CREATE_DT FROM LABEL_MASTER L
L.DOMAIN_ID = #{domainId} AND L.COMPANY_CD = #{companyCd} AND L.EMAIL = #{email}
AND L.LABEL_NM LIKE REPLACE(CONCAT('%', #{labelNm}, '%'), ' ','')
ORDER BY LABEL_NM
LIMIT #{start}, #{length}

SELECT 
	COUNT(*)
FROM
	LABEL_MASTER L

	L.DOMAIN_ID = #{domainId}
	AND L.COMPANY_CD = #{companyCd}
	AND L.EMAIL = #{email}

		AND L.LABEL_NM LIKE REPLACE(CONCAT('%', #{labelNm}, '%'), ' ','')

